A4SRAI_DIAGRAM_B64 = ""


def diagram_bytes():
    """Return the A4SRAI diagram as bytes, or None if unavailable."""
    try:
        if A4SRAI_DIAGRAM_B64 and not A4SRAI_DIAGRAM_B64.startswith("__"):
            return base64.b64decode(A4SRAI_DIAGRAM_B64)
    except Exception:
        pass
    return None


