# Plain-English explanations of each responsible-AI principle (what it means + how
# to put it into practice), reused as tooltips and in the Learn module.
RAI_EXPLAIN = {
    "Fairness": ("The system treats people and groups equitably and avoids discrimination. "
                 "In practice: test outcomes across groups and correct disparities. Example: "
                 "identical CVs should score the same regardless of the candidate's name."),
    "Safety": ("The system avoids causing harm and fails safely. In practice: constrain harmful "
               "outputs, add human oversight for high-stakes actions, and test worst cases. "
               "Example: a health bot escalates red-flag symptoms rather than reassuring."),
    "Privacy": ("Personal data is protected and not exposed or inferred without consent. In "
                "practice: minimise data, filter PII from outputs, and test for leakage. "
                "Example: a bank assistant never reveals another customer's details."),
    "Security": ("The system resists manipulation, misuse and unauthorised access. In practice: "
                 "defend against prompt injection, enforce access controls, least-privilege any "
                 "actions. Example: injected text in a document can't make it move money."),
    "Transparency": ("People can understand what the system does, its limits, and how it decides. "
                     "In practice: document behaviour, disclose AI use, offer explanations and "
                     "appeals. Example: a rejected candidate learns the main factors and how to contest."),
    "Accountability": ("There are clear owners and records for the system's decisions. In "
                       "practice: assign responsibility, log decisions, keep an audit trail. "
                       "Example: every automated rejection is logged and reviewable."),
    "Human oversight": ("Humans can monitor, intervene in and override the system. In practice: "
                        "add human-in-the-loop for high-impact actions and clear escalation paths. "
                        "Example: a clinician reviews the bot's urgent triage before action."),
    "Robustness": ("The system stays reliable under noisy, unexpected or adversarial conditions. "
                   "In practice: test with edge cases and adversarial inputs and monitor for drift. "
                   "Example: small perturbations shouldn't flip a classifier's decision."),
}

