# --------------------------------------------------------------------------- #
# Data helpers
# --------------------------------------------------------------------------- #
def _s(v) -> str:
    try:
        if pd.isna(v):
            return ""
    except (TypeError, ValueError):
        pass
    return str(v)


def blank_rows(n: int = 1) -> pd.DataFrame:
    return pd.DataFrame([{c: None for c in COLS} for _ in range(n)])


def _as_ordered_cat(series: pd.Series, categories: list) -> pd.Categorical:
    """Ordered categorical robust to stray values (anything not in `categories`
    becomes NaN rather than raising on newer pandas)."""
    vals = series.astype(object)
    vals = vals.where(vals.isin(categories), other=None)
    return pd.Categorical(vals, categories=categories, ordered=True)


def normalise(df: pd.DataFrame) -> pd.DataFrame:
    """Enforce the register schema and make the choice columns ordered categoricals
    (which gives dropdown editors in st.data_editor)."""
    df = df.copy()
    for c in COLS:
        if c not in df.columns:
            df[c] = None
    df = df[COLS]
    df["Risk"] = df["Risk"].astype("string")
    df["Controls"] = df["Controls"].astype("string")
    df["Stage"] = _as_ordered_cat(df["Stage"], STAGES)
    df["RAI principle"] = _as_ordered_cat(df["RAI principle"], RAI_PRINCIPLES)
    df["Attack type"] = _as_ordered_cat(df["Attack type"], ATTACK_TYPES)
    df["Likelihood"] = _as_ordered_cat(df["Likelihood"], LIKELIHOOD)
    df["Impact"] = _as_ordered_cat(df["Impact"], IMPACT)
    return df.reset_index(drop=True)


def scored(df: pd.DataFrame) -> pd.DataFrame:
    """Named risks with a numeric risk score (likelihood x impact)."""
    rows = []
    for _, r in df.iterrows():
        risk = _s(r["Risk"]).strip()
        if not risk:
            continue
        l, i = _s(r["Likelihood"]), _s(r["Impact"])
        ln, iN = SCORE.get(l), SCORE.get(i)
        rows.append({
            "Risk": risk,
            "Stage": _s(r["Stage"]) or "-",
            "RAI principle": _s(r["RAI principle"]) or "-",
            "Attack type": _s(r["Attack type"]) or "-",
            "Likelihood": l or "-",
            "Impact": i or "-",
            "Score": (ln * iN) if (ln and iN) else None,
            "Controls": _s(r["Controls"]),
        })
    return pd.DataFrame(rows, columns=["Risk", "Stage", "RAI principle", "Attack type",
                                       "Likelihood", "Impact", "Score", "Controls"])


def sorted_view(df: pd.DataFrame) -> pd.DataFrame:
    """Read-only view whose Likelihood/Impact sort by severity on header click.
    (Streamlit's grid sorts text alphabetically, so we number the levels.)"""
    rows = []
    for _, r in df.iterrows():
        risk = _s(r["Risk"]).strip()
        stage = _s(r["Stage"]).strip()
        rai = _s(r["RAI principle"]).strip()
        atk = _s(r["Attack type"]).strip()
        controls = _s(r["Controls"]).strip()
        ln = SCORE.get(_s(r["Likelihood"]))
        iN = SCORE.get(_s(r["Impact"]))
        if not (risk or stage or rai or atk or controls or ln or iN):
            continue
        rows.append({
            "Risk": risk, "Stage": stage, "RAI principle": rai, "Attack type": atk,
            "Likelihood": LEVEL_LABEL.get(ln, ""), "Impact": LEVEL_LABEL.get(iN, ""),
            "Score": (ln * iN) if (ln and iN) else None, "Control(s)": controls,
        })
    out = pd.DataFrame(rows, columns=["Risk", "Stage", "RAI principle", "Attack type",
                                      "Likelihood", "Impact", "Score", "Control(s)"])
    return out.sort_values("Score", ascending=False, na_position="last").reset_index(drop=True)


def zone_colour(score: int) -> str:
    if score >= 6:
        return ZONE_RED
    if score >= 3:
        return ZONE_AMBER
    return ZONE_GREEN


def tier_of(score):
    if score is None:
        return "Unscored", "#9e9e9e"
    if score >= 6:
        return "High", ZONE_RED
    if score >= 3:
        return "Medium", ZONE_AMBER
    return "Low", ZONE_GREEN


def coverage(df: pd.DataFrame) -> dict:
    """Which RAI principles, attack types and lifecycle stages have >=1 named risk,
    plus a component x RAI count grid."""
    sc = scored(df)
    rai_seen, atk_seen, stage_seen, comp_seen = set(), set(), set(), set()
    grid = {c: {p: 0 for p in RAI_PRINCIPLES} for c in COMPONENTS}
    for _, r in sc.iterrows():
        p, a, s = r["RAI principle"], r["Attack type"], r["Stage"]
        if p in RAI_PRINCIPLES:
            rai_seen.add(p)
        if a in ATTACK_TYPES and a != "Other":
            atk_seen.add(a)
        if s in STAGE_TO_COMPONENT:
            stage_seen.add(s)
            comp = STAGE_TO_COMPONENT[s]
            comp_seen.add(comp)
            if p in RAI_PRINCIPLES:
                grid[comp][p] += 1
    return {
        "n_risks": len(sc),
        "rai_seen": rai_seen, "rai_missing": [p for p in RAI_PRINCIPLES if p not in rai_seen],
        "atk_seen": atk_seen,
        "atk_missing": [a for a in ATTACK_TYPES if a != "Other" and a not in atk_seen],
        "stage_seen": stage_seen, "stage_missing": [s for s in STAGES if s not in stage_seen],
        "comp_seen": comp_seen, "comp_missing": [c for c in COMPONENTS if c not in comp_seen],
        "grid": grid,
    }


def records_from_df(df: pd.DataFrame) -> list:
    out = []
    for _, r in df.iterrows():
        out.append({c: (None if _s(r[c]) == "" else _s(r[c])) for c in COLS})
    return out


def df_from_records(records) -> pd.DataFrame:
    if not records:
        return normalise(blank_rows(3))
    return normalise(pd.DataFrame(records))


def parse_pasted_risks(text: str) -> pd.DataFrame:
    """Parse a Markdown pipe-table or CSV of risks into the register schema.
    Maps columns by header keywords; falls back to positional order if no header."""
    text = (text or "").strip()
    if not text:
        return blank_rows(0)

    lines = [ln for ln in text.splitlines() if ln.strip()]
    table = []
    if any("|" in ln for ln in lines):
        for ln in lines:
            if "|" not in ln:
                continue
            cells = [c.strip() for c in ln.strip().strip("|").split("|")]
            if cells and all(set(c) <= set("-: ") for c in cells):
                continue  # markdown separator row
            table.append(cells)
    else:
        for row in csv.reader(io.StringIO(text)):
            if any(c.strip() for c in row):
                table.append([c.strip() for c in row])

    if not table:
        return blank_rows(0)

    keymap = [
        (["risk", "vulnerab", "threat"], "Risk"),
        (["stage", "phase"], "Stage"),
        (["rai", "principle"], "RAI principle"),
        (["attack", "technique"], "Attack type"),
        (["likelihood", "probab"], "Likelihood"),
        (["impact", "severity", "consequence"], "Impact"),
        (["control", "mitigat", "safeguard"], "Controls"),
    ]
    header = [h.lower() for h in table[0]]

    def _is_header(cells):
        joined = " ".join(cells)
        return any(any(k in joined for k in ks) for ks, _ in keymap)

    if _is_header(header):
        col_idx = {}
        for i, h in enumerate(header):
            for ks, col in keymap:
                if col not in col_idx and any(k in h for k in ks):
                    col_idx[col] = i
        rows = []
        for cells in table[1:]:
            rec = {c: None for c in COLS}
            for col, i in col_idx.items():
                if i < len(cells) and cells[i]:
                    rec[col] = cells[i]
            rows.append(rec)
    else:
        rows = []
        for cells in table:
            rec = {c: None for c in COLS}
            for i, col in enumerate(COLS):
                if i < len(cells) and cells[i]:
                    rec[col] = cells[i]
            rows.append(rec)

    df = pd.DataFrame(rows)

    def _match(val, vocab):
        if not val:
            return None
        v = str(val).strip().lower()
        for opt in vocab:
            if v == opt.lower():
                return opt
        for opt in vocab:
            if opt.lower() in v or v in opt.lower():
                return opt
        return None

    for col, vocab in [("Likelihood", LIKELIHOOD), ("Impact", IMPACT), ("Stage", STAGES),
                       ("RAI principle", RAI_PRINCIPLES), ("Attack type", ATTACK_TYPES)]:
        if col in df:
            df[col] = df[col].map(lambda x: _match(x, vocab))

    if "Risk" in df:
        keep = [bool(_s(v).strip()) for v in df["Risk"]]
        df = df[keep]
    return normalise(df) if len(df) else blank_rows(0)


def genai_prompt(s: dict) -> str:
    feats = "\n".join(f"- {f}" for f in s["features"])
    rai = ", ".join(s["rai_focus"])
    stages = ", ".join(STAGES)
    return (
        "You are an AI risk and red-teaming assistant. Analyse the AI system described below "
        "using an AI red-teaming mindset (adversarial exploration, bias probing and misuse "
        "simulation) and the Agile 4 Secure Responsible AI (A4SRAI) approach, where red teaming "
        "runs across the whole Agile lifecycle.\n\n"
        f"AI SYSTEM: {s['name']}\n"
        f"WHAT IT IS: {s['description']}\n\n"
        f"KEY FEATURES:\n{feats}\n\n"
        f"USERS & STAKEHOLDERS: {s['users']}\n"
        f"DATA USED: {s['data']}\n"
        f"DEPLOYMENT CONTEXT: {s['deployment']}\n"
        f"RESPONSIBLE-AI CONCERNS TO PROBE: {rai}\n\n"
        "TASK:\n"
        "Identify at least 5 concrete, specific risks. For EACH risk, give:\n"
        "1. Risk - a clear, specific description\n"
        f"2. Stage - the A4SRAI/Agile stage most relevant, from: {stages}\n"
        f"3. RAI principle - one of: {', '.join(RAI_PRINCIPLES)}\n"
        f"4. Attack type - one of: {', '.join(ATTACK_TYPES)}\n"
        "5. Likelihood - Low, Medium or High\n"
        "6. Impact - Low, Medium or High\n"
        "7. Control - a practical mitigation\n\n"
        "Return ONLY a Markdown table with these exact columns:\n"
        "| Risk | Stage | RAI principle | Attack type | Likelihood | Impact | Control |\n"
        "Keep each cell concise so it can be pasted straight into a risk register."
    )


def render_matrix(df: pd.DataFrame, project: str) -> Figure:
    """3x3 likelihood x impact risk matrix (thread-safe OO Figure)."""
    idx = {"Low": 0, "Medium": 1, "High": 2}
    cells = [[[] for _ in range(3)] for _ in range(3)]
    for _, r in df.iterrows():
        risk = _s(r["Risk"]).strip()
        l, i = _s(r["Likelihood"]), _s(r["Impact"])
        if risk and l in idx and i in idx:
            cells[idx[i]][idx[l]].append(risk)

    fig = Figure(figsize=(6.6, 6.0))
    ax = fig.subplots()
    for col in range(3):
        for row in range(3):
            score = (col + 1) * (row + 1)
            ax.add_patch(Rectangle((col, row), 1, 1, facecolor=zone_colour(score),
                                   edgecolor="white", linewidth=3, alpha=0.85))
            names = cells[row][col]
            ax.text(col + 0.5, row + 0.86, f"{len(names)}", ha="center", va="center",
                    fontsize=15, fontweight="bold", color="#1a1a1a")
            if names:
                shown = [textwrap.shorten(n, width=18, placeholder="...") for n in names[:3]]
                if len(names) > 3:
                    shown.append(f"+{len(names) - 3} more")
                ax.text(col + 0.5, row + 0.40, "\n".join(shown), ha="center", va="center",
                        fontsize=7.5, color="#1a1a1a")
    ax.set_xlim(0, 3)
    ax.set_ylim(0, 3)
    ax.set_xticks([0.5, 1.5, 2.5])
    ax.set_xticklabels(LIKELIHOOD)
    ax.set_yticks([0.5, 1.5, 2.5])
    ax.set_yticklabels(IMPACT)
    ax.set_xlabel("Likelihood \u2192", fontsize=11)
    ax.set_ylabel("Impact \u2192", fontsize=11)
    ax.set_title(f"Risk Matrix \u2014 {project}", fontsize=13, fontweight="bold", pad=12)
    ax.set_aspect("equal")
    for sp in ax.spines.values():
        sp.set_visible(False)
    ax.tick_params(length=0)
    fig.tight_layout()
    return fig


def render_coverage_grid(cov: dict) -> Figure:
    """Heatmap of A4SRAI component (rows) x RAI principle (cols) counts."""
    comps = list(COMPONENTS.keys())
    fig = Figure(figsize=(8.4, 3.6))
    ax = fig.subplots()
    for r, comp in enumerate(comps):
        for c, pr in enumerate(RAI_PRINCIPLES):
            n = cov["grid"][comp][pr]
            colour = "#ece9f3" if n == 0 else COMPONENTS[comp]["color"]
            txtcol = "#9a9a9a" if n == 0 else "#ffffff"
            ax.add_patch(Rectangle((c, r), 1, 1, facecolor=colour, edgecolor="white", linewidth=2))
            ax.text(c + 0.5, r + 0.5, str(n), ha="center", va="center",
                    fontsize=10, fontweight="bold", color=txtcol)
    ax.set_xlim(0, len(RAI_PRINCIPLES))
    ax.set_ylim(0, len(comps))
    ax.set_xticks([i + 0.5 for i in range(len(RAI_PRINCIPLES))])
    ax.set_xticklabels(RAI_PRINCIPLES, rotation=35, ha="right", fontsize=8)
    ax.set_yticks([i + 0.5 for i in range(len(comps))])
    ax.set_yticklabels(comps, fontsize=8)
    ax.invert_yaxis()
    ax.set_title("Coverage: risks logged per component \u00d7 RAI principle",
                 fontsize=11, fontweight="bold")
    for sp in ax.spines.values():
        sp.set_visible(False)
    ax.tick_params(length=0)
    fig.tight_layout()
    return fig


def build_pdf_report(project: str, df: pd.DataFrame, cov: dict, learner: str):
    """Red-team report as a PDF (reportlab). Returns bytes or None if reportlab missing."""
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.lib.units import cm
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle)
    except Exception:
        return None

    sc = scored(df)
    valid = sc.dropna(subset=["Score"]).sort_values("Score", ascending=False)
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, leftMargin=1.8 * cm, rightMargin=1.8 * cm,
                            topMargin=1.8 * cm, bottomMargin=1.8 * cm,
                            title=f"RedLoop report - {project}")
    styles = getSampleStyleSheet()
    h = styles["Heading1"]; h.textColor = colors.HexColor("#B0224B")
    sub = ParagraphStyle("sub", parent=styles["Normal"], textColor=colors.HexColor("#666666"))
    body = styles["Normal"]
    story = [Paragraph(f"{APP_NAME} - AI Red-Team Report", h),
             Paragraph(f"System: <b>{project}</b>", body),
             Paragraph(f"Prepared by: {learner or 'RedLoop learner'} &nbsp;·&nbsp; "
                       f"{_dt.date.today().isoformat()}", sub),
             Spacer(1, 10)]

    n_high = int((valid["Score"] >= 6).sum())
    n_med = int(((valid["Score"] >= 3) & (valid["Score"] < 6)).sum())
    n_low = int((valid["Score"] < 3).sum())
    story.append(Paragraph("Summary", styles["Heading2"]))
    story.append(Paragraph(
        f"{len(valid)} scored risk(s): {n_high} high, {n_med} medium, {n_low} low. "
        f"Responsible-AI principles covered: {len(cov['rai_seen'])}/{len(RAI_PRINCIPLES)}. "
        f"Lifecycle stages with findings: {len(cov['stage_seen'])}/{len(STAGES)}.", body))
    if cov["rai_missing"]:
        story.append(Paragraph("Blind spots (RAI principles not yet probed): "
                               + ", ".join(cov["rai_missing"]), body))
    story.append(Spacer(1, 10))

    story.append(Paragraph("Risk register (highest severity first)", styles["Heading2"]))
    data = [["Risk", "Stage", "RAI", "Attack", "L", "I", "Score", "Control(s)"]]
    for _, r in valid.iterrows():
        data.append([Paragraph(_s(r["Risk"]), body), Paragraph(_s(r["Stage"]), body),
                     Paragraph(_s(r["RAI principle"]), body), Paragraph(_s(r["Attack type"]), body),
                     _s(r["Likelihood"])[:1], _s(r["Impact"])[:1], str(int(r["Score"])),
                     Paragraph(_s(r["Controls"]), body)])
    if len(data) == 1:
        data.append([Paragraph("No scored risks yet.", body), "", "", "", "", "", "", ""])
    tbl = Table(data, colWidths=[4.6 * cm, 2.2 * cm, 2.0 * cm, 2.0 * cm,
                                 0.7 * cm, 0.7 * cm, 1.0 * cm, 3.4 * cm], repeatRows=1)
    tbl.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#B0224B")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("FONTSIZE", (0, 0), (-1, -1), 7),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#cccccc")),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#f6f2f4")]),
    ]))
    story.append(tbl)
    story.append(Spacer(1, 12))
    story.append(Paragraph("Generated with RedLoop - red teaming across the A4SRAI lifecycle "
                           "(Agile Planning \u2192 Adversarial Mapping \u2192 Iterative Red "
                           "Teaming \u2192 Governance Loop).", sub))
    doc.build(story)
    return buf.getvalue()


def build_certificate_pdf(name: str, score_pct: int):
    """Completion certificate PDF (reportlab). Returns bytes or None."""
    try:
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib import colors
        from reportlab.lib.units import cm
        from reportlab.pdfgen import canvas
    except Exception:
        return None
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4))
    w, hh = landscape(A4)
    c.setStrokeColor(colors.HexColor("#B0224B")); c.setLineWidth(4)
    c.rect(1.2 * cm, 1.2 * cm, w - 2.4 * cm, hh - 2.4 * cm)
    c.setFillColor(colors.HexColor("#B0224B")); c.setFont("Helvetica-Bold", 30)
    c.drawCentredString(w / 2, hh - 4 * cm, "Certificate of Completion")
    c.setFillColor(colors.black); c.setFont("Helvetica", 16)
    c.drawCentredString(w / 2, hh - 6 * cm, "This certifies that")
    c.setFont("Helvetica-Bold", 24)
    c.drawCentredString(w / 2, hh - 7.6 * cm, name or "RedLoop learner")
    c.setFont("Helvetica", 15)
    c.drawCentredString(w / 2, hh - 9.4 * cm,
                        "has completed RedLoop: AI Red Teaming with the A4SRAI framework")
    c.drawCentredString(w / 2, hh - 10.6 * cm, f"Assessment score: {score_pct}%")
    c.setFont("Helvetica-Oblique", 12)
    c.drawCentredString(w / 2, hh - 12.4 * cm, _dt.date.today().isoformat())
    c.showPage(); c.save()
    return buf.getvalue()


