def init_state():
    ss = st.session_state
    ss.setdefault("saved", {})
    ss.setdefault("baseline", {})
    ss.setdefault("enonce", {})
    ss.setdefault("active_project", None)
    ss.setdefault("show_matrix", False)
    ss.setdefault("progress", {})
    ss.setdefault("learner_name", "")
    ss.setdefault("pre_done", False)
    ss.setdefault("pre_score", None)
    ss.setdefault("post_done", False)
    ss.setdefault("post_score", None)
    ss.setdefault("sel_stage", STAGES[0])
    ss.setdefault("nav", "Home")
    for m in MODULES:
        ss.progress.setdefault(m, False)


def mark_done(module: str):
    st.session_state.progress[module] = True


def complete_button(module: str):
    """Render a 'Mark complete' control that updates progress immediately.

    The sidebar (and its progress bar) is drawn *before* the page body on each
    run, so simply setting progress inside a button handler wouldn't refresh the
    bar until the next interaction. Setting progress and calling st.rerun() makes
    the bar advance the moment the button is pressed once.
    """
    done = st.session_state.progress.get(module, False)
    if done:
        st.success(f"\u2705 You've completed '{module}'.")
    if st.button(f"\u2705 Mark '{module}' complete", key=f"complete_{module}", disabled=done):
        st.session_state.progress[module] = True
        st.session_state["_flash"] = f"'{module}' marked complete \u2014 progress updated."
        st.rerun()


def ensure_project(project: str):
    ss = st.session_state
    if project not in ss.baseline:
        ss.baseline[project] = normalise(ss.saved.get(project, blank_rows(3)))
        ss.enonce[project] = 0
    if ss.active_project != project:
        ss.baseline[project] = normalise(ss.saved.get(project, ss.baseline[project]))
        ss.enonce[project] = ss.enonce.get(project, 0) + 1
        ss.active_project = project


def append_to_register(project: str, new_df: pd.DataFrame):
    """Append parsed/entered risks to a project's register (structural change ->
    reseed the editor with a fresh key)."""
    ss = st.session_state
    cur = ss.saved.get(project)
    keep = normalise(cur) if cur is not None else normalise(blank_rows(0))
    keep = keep[[bool(_s(v).strip()) for v in keep["Risk"]]] if len(keep) else keep
    combined = pd.concat([keep.astype(object), normalise(new_df).astype(object)],
                         ignore_index=True)
    combined = normalise(combined)
    if len(combined) == 0:
        combined = normalise(blank_rows(3))
    ss.saved[project] = combined
    ss.baseline[project] = combined
    ss.enonce[project] = ss.enonce.get(project, 0) + 1


def chip(text, bg, fg="#ffffff", title=None):
    """A coloured pill. If `title` is given, it renders an ⓘ marker and a native
    hover tooltip (HTML title attribute)."""
    attr = ""
    label = text
    if title:
        attr = f' title="{_html.escape(str(title), quote=True)}"'
        label = f"{text} \u24d8"
    return (f"<span{attr} style='background:{bg};color:{fg};padding:2px 9px;border-radius:11px;"
            f"font-size:12px;white-space:nowrap;cursor:default;'>{label}</span>")


def component_badge(component: str):
    return chip(component, COMPONENTS.get(component, {}).get("color", "#6E6E6E"))


