def _markdown_report(project, df, cov):
    sc = scored(df).dropna(subset=["Score"]).sort_values("Score", ascending=False)
    lines = [f"# RedLoop - AI Red-Team Report", f"**System:** {project}  ",
             f"**Prepared by:** {st.session_state.learner_name or 'RedLoop learner'}  ",
             f"**Date:** {_dt.date.today().isoformat()}", "",
             "## Summary",
             f"- Scored risks: {len(sc)}",
             f"- RAI principles covered: {len(cov['rai_seen'])}/{len(RAI_PRINCIPLES)}",
             f"- Lifecycle stages with findings: {len(cov['stage_seen'])}/{len(STAGES)}"]
    if cov["rai_missing"]:
        lines.append(f"- Blind spots (RAI not probed): {', '.join(cov['rai_missing'])}")
    lines += ["", "## Risk register (highest severity first)", "",
              "| Risk | Stage | RAI | Attack | Likelihood | Impact | Score | Control |",
              "|---|---|---|---|---|---|---|---|"]
    for _, r in sc.iterrows():
        lines.append(f"| {r['Risk']} | {r['Stage']} | {r['RAI principle']} | {r['Attack type']} "
                     f"| {r['Likelihood']} | {r['Impact']} | {int(r['Score'])} | {r['Controls']} |")
    if len(sc) == 0:
        lines.append("| _No scored risks yet_ | | | | | | | |")
    return "\n".join(lines)


def _export_session_json():
    ss = st.session_state
    data = {
        "app": APP_NAME, "version": 1,
        "learner_name": ss.learner_name,
        "registers": {p: records_from_df(df) for p, df in ss.saved.items()},
        "progress": ss.progress,
        "pre_done": ss.pre_done, "pre_score": ss.pre_score,
        "post_done": ss.post_done, "post_score": ss.post_score,
    }
    import json as _json
    return _json.dumps(data, indent=2)


def _import_session_json(text):
    import json as _json
    data = _json.loads(text)
    ss = st.session_state
    ss.learner_name = data.get("learner_name", "")
    ss.saved = {p: df_from_records(recs) for p, recs in data.get("registers", {}).items()}
    ss.baseline = {}
    ss.enonce = {}
    ss.active_project = None
    prog = data.get("progress", {})
    ss.progress = {m: bool(prog.get(m, False)) for m in MODULES}
    ss.pre_done = bool(data.get("pre_done", False))
    ss.pre_score = data.get("pre_score")
    ss.post_done = bool(data.get("post_done", False))
    ss.post_score = data.get("post_score")


