def main():
    st.set_page_config(page_title=f"{APP_NAME} - AI Red Teaming with A4SRAI",
                       page_icon="\U0001F501", layout="wide")
    init_state()
    _flash = st.session_state.pop("_flash", None)
    if _flash:
        st.toast(_flash, icon="\u2705")
    choice = render_sidebar()
    PAGES.get(choice, page_home)()


if __name__ == "__main__":
    main()
